#!/usr/bin/env node
/**
 * Generates `src/environments/environment.ts` from `.env` and `process.env`.
 *
 * The generated file is git-ignored so API keys never end up in source control.
 * Runs automatically via the `postinstall`, `prestart`, `prebuild`, `prewatch`
 * and `pretest` npm hooks; run `npm run env` to regenerate manually.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const envFile = resolve(root, '.env');
const target = resolve(root, 'src/environments/environment.ts');

/** Minimal .env parser: KEY=value, `#` comments, optional single/double quotes. */
function parseDotEnv(text) {
  const out = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    const quoted =
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"));
    if (quoted) value = value.slice(1, -1);
    out[key] = value;
  }
  return out;
}

const fileVars = existsSync(envFile) ? parseDotEnv(readFileSync(envFile, 'utf8')) : {};
const read = (key) => (process.env[key] ?? fileVars[key] ?? '').trim();

const env = {
  maptilerApiKey: read('MAPTILER_API_KEY'),
  mapStyleUrl: read('MAP_STYLE_URL'),
};

const banner = [
  '// AUTO-GENERATED by scripts/set-env.mjs — do not edit and do not commit.',
  '// Values come from `.env` / process.env; see `.env.example` for the list of variables.',
  '',
].join('\n');

const body =
  'export interface AppEnvironment {\n' +
  '  /** MapTiler API key. Empty → CARTO Dark Matter (no key required). */\n' +
  '  maptilerApiKey: string;\n' +
  '  /** Explicit MapLibre style.json URL. Empty → provider default. */\n' +
  '  mapStyleUrl: string;\n' +
  '}\n\n' +
  `export const environment: AppEnvironment = ${JSON.stringify(env, null, 2)};\n`;

mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, banner + body, 'utf8');

const source = env.mapStyleUrl
  ? 'custom MAP_STYLE_URL'
  : env.maptilerApiKey
    ? 'MapTiler (key present)'
    : 'CARTO Dark Matter (no key needed)';
console.log(`[set-env] wrote src/environments/environment.ts → map provider: ${source}`);
